                    pulseId: round.pulseId,
                    teamId: round.teamId,
                    status: round.status,
                    plannedOpenDate: round.plannedOpenDate,
                    anonymityMode: round.anonymityMode,
                    closedAt: round.closedAt,
                    effectiveMinimumGroupSize: effectiveN,
                    eligibleMembersCount,
                    questions,
                    submissions,
                    pastRoundsHistory: [],
