169	/** Lowercased words of `text` with diacritics removed, split on anything that is not a letter or a number. */
170	const wordsOf = (text: string): ReadonlyArray<string> =>
171	  text
172	    .normalize("NFKD")
173	    .replace(/\p{M}/gu, "")
174	    .toLowerCase()
175	    .split(/[^\p{L}\p{N}]+/u)
176	    .filter((word) => word.length > 0);
177	
178	/** Every window of QUOTE_RUN_WORDS consecutive words, joined by a space. */
179	const runsOf = (text: string): Set<string> => {
180	  const words = wordsOf(text);
181	  const runs = new Set<string>();
182	  for (let i = 0; i + QUOTE_RUN_WORDS <= words.length; i++) {
183	    runs.add(words.slice(i, i + QUOTE_RUN_WORDS).join(" "));
184	  }
185	  return runs;
186	};
187	
188	/** True when `text` repeats QUOTE_RUN_WORDS or more consecutive words of any comment (ADR 0016). */
189	export const repeatsCommentWords = (text: string, comments: ReadonlyArray<string>): boolean => {
190	  const commentRuns = new Set(comments.flatMap((comment) => [...runsOf(comment)]));
191	  return [...runsOf(text)].some((run) => commentRuns.has(run));
192	};
