194	export class ThemesReplyInvalid extends Data.TaggedError("ThemesReplyInvalid") {}
195	
196	const ReplyEnvelope = Schema.Struct({
197	  themes: Schema.Array(Schema.Unknown),
198	  guide: Schema.optionalKey(Schema.Unknown),
199	});
200	
201	const ThemeReply = Schema.Struct({
202	  label: Schema.String.pipe(Schema.check(Schema.isMinLength(1))),
203	  sentence: Schema.String.pipe(Schema.check(Schema.isMinLength(1))),
204	  supportingCommentIndexes: Schema.Array(Schema.Int),
205	});
206	
207	const decodeEnvelope = Schema.decodeUnknownOption(ReplyEnvelope);
208	const decodeThemeReply = Schema.decodeUnknownOption(ThemeReply);
209	const decodeGuide = Schema.decodeUnknownOption(DiscussionGuide);
210	
211	/**
212	 * ADR 0016/0019 checks on the model's reply. Fails only when the top level is not an object with a
213	 * `themes` array. Otherwise the reply is cleaned, never repaired:
214	 * - only the first MAX_THEMES entries are considered; an entry that does not decode is dropped;
215	 * - supportingComments counts distinct in-range comment indexes; fewer than 2 drops the theme;
216	 * - a label or sentence that repeats a 6-word run of any comment drops the theme;
217	 * - the guide must decode as DiscussionGuide, and no string in it may repeat a 6-word run; otherwise
218	 *   the whole guide is null.
219	 */
220	export const checkThemesReply = (
221	  reply: unknown,
222	  comments: ReadonlyArray<string>,
223	): Effect.Effect<StoredThemes, ThemesReplyInvalid> => {
224	  const envelope = Option.getOrNull(decodeEnvelope(reply));
225	  if (envelope === null) {
226	    return Effect.fail(new ThemesReplyInvalid());
227	  }
228	
229	  const themes = envelope.themes.slice(0, MAX_THEMES).flatMap((entry) => {
230	    const decoded = Option.getOrNull(decodeThemeReply(entry));
231	    if (decoded === null) return [];
232	    const supporters = new Set(
233	      decoded.supportingCommentIndexes.filter((index) => index >= 0 && index < comments.length),
234	    ).size;
235	    if (supporters < MIN_SUPPORTING_COMMENTS) return [];
236	    if (repeatsCommentWords(decoded.label, comments) || repeatsCommentWords(decoded.sentence, comments)) {
237	      return [];
238	    }
239	    return [{ label: decoded.label, sentence: decoded.sentence, supportingComments: supporters }];
240	  });
241	
242	  const guide = Option.getOrNull(decodeGuide(envelope.guide));
243	  const guideRepeats =
244	    guide === null ||
245	    [...guide.whatStoodOut, ...guide.whatPeopleRaised, ...guide.actionsToCheckOn, ...guide.questions].some(
246	      (text) => repeatsCommentWords(text, comments),
247	    );
248	
249	  return Effect.succeed({ themes, guide: guideRepeats ? null : guide });
250	};
251	
252	/**
253	 * Backoff for the k-th failed attempt (k >= 1): min(5 min * 2^(k-1), 4 h). Returns the next due
254	 * time, or null when it would fall after requestedAt + 24 h (give up).
255	 */
256	export const nextThemesAttemptAt = (
257	  requestedAt: number,
258	  failedAttempts: number,
259	  now: number,
260	): number | null => {
261	  const k = Math.max(1, failedAttempts);
262	  const gap = Math.min(FIRST_RETRY_GAP_MS * 2 ** (k - 1), MAX_RETRY_GAP_MS);
263	  const dueAt = now + gap;
264	  return dueAt > requestedAt + THEMES_RETRY_WINDOW_MS ? null : dueAt;
265	};
266	
267	export type ThemesJobDecision =
268	  | { readonly _tag: "Store"; readonly themes: StoredThemes }
269	  | { readonly _tag: "RetryAt"; readonly dueAt: number; readonly attempts: number }
270	  | { readonly _tag: "GiveUp" };
271	
272	/**
273	 * One attempt of the Round's single themes call. AiNotConfigured gives up, since nothing will change.
274	 * AiRejected, AiUnavailable and ThemesReplyInvalid retry at the backoff time, or give up once the
275	 * window is over. Never logs the reply or an error body.
276	 */
277	export const runThemesAttempt = (params: {
278	  readonly input: AiInput;
279	  readonly requestedAt: number;
280	  readonly attempts: number;
281	  readonly now: number;
282	}): Effect.Effect<ThemesJobDecision, never, AiClient> => {
283	  const comments = params.input.comments.map((c) => c.text);
284	  const retry = (): ThemesJobDecision => {
285	    const failedAttempts = params.attempts + 1;
286	    const dueAt = nextThemesAttemptAt(params.requestedAt, failedAttempts, params.now);
287	    return dueAt === null ? { _tag: "GiveUp" } : { _tag: "RetryAt", dueAt, attempts: failedAttempts };
288	  };
289	
290	  return AiClient.use((client) => client.complete(themesRequest(params.input))).pipe(
291	    Effect.flatMap((reply) => checkThemesReply(reply, comments)),
292	    Effect.map((themes): ThemesJobDecision => ({ _tag: "Store", themes })),
293	    Effect.catchTags({
294	      AiNotConfigured: (): Effect.Effect<ThemesJobDecision> => Effect.succeed({ _tag: "GiveUp" }),
295	      AiRejected: (): Effect.Effect<ThemesJobDecision> => Effect.succeed(retry()),
296	      AiUnavailable: (): Effect.Effect<ThemesJobDecision> => Effect.succeed(retry()),
297	      ThemesReplyInvalid: (): Effect.Effect<ThemesJobDecision> => Effect.succeed(retry()),
298	    }),
299	  );
300	};
