302	/**
303	 * The Result as one viewer may see it (ADR 0004, 0016, 0019). Single source of truth used by the
304	 * Organization object and the privacy tests.
305	 */
306	export const viewRoundResult = (params: {
307	  readonly stored: RoundResult;
308	  readonly organizationN: number;
309	  readonly isLead: boolean;
310	  readonly themes: RoundThemesRecord | null;
311	}): RoundResult => {
312	  const r = enforceEffectiveNOnResult(params.stored, params.organizationN);
313	  const shown: RoundResult = { ...r, comments: params.isLead ? r.comments : [] };
314	
315	  const hidden = (status: "notRequested" | "preparing" | "unavailable"): RoundResult => ({
316	    ...shown,
317	    themesStatus: status,
318	    themes: [],
319	    ...(params.isLead ? { discussionGuide: null } : {}),
320	  });
321	
322	  const record = params.themes;
323	  if (!r.meetsMinimumGroupSize || record === null) return hidden("notRequested");
324	
325	  switch (record.status) {
326	    case "pending":
327	      return hidden("preparing");
328	    case "failed":
329	      return hidden("unavailable");
330	    case "ready":
331	      if (!params.isLead) {
332	        return {
333	          ...shown,
334	          themesStatus: "ready",
335	          themes: record.themes.themes.map(({ label, sentence }) => ({ label, sentence })),
336	        };
337	      }
338	      return {
339	        ...shown,
340	        themesStatus: "ready",
341	        themes: record.themes.themes,
342	        discussionGuide: record.themes.guide,
343	      };
344	  }
345	};
